def do_input_types_conflict(type1: GraphQLInputType, type2: GraphQLInputType) -> bool:
    """Check whether two input types conflict

    Two input types conflict if both types could not apply to a value simultaneously.
    Composite types are ignored as their individual field types will be compared later
    recursively. However List and Non-Null types must match.
    """
    if isinstance(type1, GraphQLList) and isinstance(type2, GraphQLList):
        return do_input_types_conflict(type1.of_type, type2.of_type)

    if isinstance(type1, GraphQLNonNull) and isinstance(type2, GraphQLNonNull):
        return do_input_types_conflict(type1.of_type, type2.of_type)

    if isinstance(type1, GraphQLNonNull) or isinstance(type2, GraphQLNonNull):
        return False

    return type1 != type2


