def parse_changelog(args: Any) -> Tuple[str, str]:
    """Return an updated changelog and and the list of changes."""
    if args.changelog is None:
        return "", ""

    with open(args.changelog, "r") as f:
        changelog = f.read()

    if args.changelog_version is None:
        return changelog, ""

    version = args.changelog_version
    if version not in changelog:
        return changelog, ""

    start = changelog.find(version)
    end = changelog.find("\n", start)
    return changelog[:start] + changelog[end:], changelog[start:end]

