def estimate_gas_for_function(
        address,
        web3,
        fn_identifier=None,
        transaction=None,
        contract_abi=None,
        fn_abi=None,
        *args,
        **kwargs):
    """Estimates gas cost a function call would take.

    Don't call this directly, instead use :meth:`Contract.estimateGas`
    on your contract instance.
    """
    if fn_identifier is None:
        if transaction is None:
            raise ValueError("Must provide either fn_identifier or transaction")
        else:
            fn_identifier = transaction['to']

    if transaction is None:
        transaction = {}

    if contract_abi is None:
        contract_abi = get_abi(address)

    if fn_abi is None:
        fn_abi = get_abi_function(contract_abi, fn_identifier)

    if 'data' not in transaction:
        transaction['data'] = encode_abi(fn_abi, *args, **kwargs)

    gas_estimate = web3.eth.estimateGas(transaction)

    return gas_estimate

