def local_replace(self, dt, use_dst=True, _recurse=False, **kwds):
        """Return pywws timestamp (utc, no tzinfo) for the most recent
        local time before the pywws timestamp dt, with datetime replace
        applied.

        """
        if _recurse:
            return dt

        if dt.tzinfo is None:
            raise ValueError('dt must have tzinfo')

        if dt.tzinfo.utcoffset(dt) is None:
            raise ValueError('dt must have a utcoffset')

        if use_dst:
            dst_offset = dt.tzinfo.dst(dt)
        else:
            dst_offset = datetime.timedelta(0)

        utc_offset = dt.tzinfo.utcoffset(dt)

        if utc_offset is None:
            raise ValueError('dt must have a utcoffset')

        local_dt = dt - utc_offset - dst_offset

        return local_dt.replace(**kwds)

