def _prepare_smoove_bams(full_bams, sr_bams, disc_bams, items, tx_work_dir):
    """Prepare BAMs for smoove, linking in pre-existing split/disc BAMs if present.

    Smoove can use pre-existing discordant and split BAMs prepared by samblaster
    if present as $sample.split.bam and $sample.disc.bam.
    """
    for item in items:
        sample = item.name
        if sample not in full_bams:
            raise ValueError("Sample %s not found in full BAMs" % sample)
        if sample not in sr_bams:
            raise ValueError("Sample %s not found in split/read BAMs" % sample)
        if sample not in disc_bams:
            raise ValueError("Sample %s not found in discordant BAMs" % sample)
        full_bam = full_bams[sample]
        sr_bam = sr_bams[sample]
        disc_bam = disc_bams[sample]
        if not os.path.exists(sr_bam):
            raise ValueError("Split/read BAM %s not found" % sr_bam)
        if not os.path.exists(disc_bam):
            raise ValueError("Discordant BAM %s not found" % disc_bam)
