def load_map(dirspec, fname):
    """ load a single map

    :param dirspec: a directory specification
    :param fname: the name of the map file
    :return: a dictionary with two keys: "to" and "fro". The values for
        those keys are the actual mapping.
    """
    with open(os.path.join(dirspec, fname), "r") as f:
        lines = f.readlines()
    map_dict = {"to": {}, "fro": {}}
    for line in lines:
        line = line.strip()
        if line.startswith("#"):
            continue
        if line.startswith("to"):
            map_dict["to"] = parse_map(line[3:])
        elif line.startswith("fro"):
            map_dict["fro"] = parse_map(line[4:])
    return map_dict


def parse_map(line):
    """ parse a map line

    :param line: the line to parse
    :return: a dictionary with the parsed mapping
    """
    mapping = {}
    for pair in line.split(";"):
        pair = pair.strip()
        if pair == "":
            continue
        key, value = pair.split("=")
        mapping[key] = value
    return mapping


