def decrypt_string(string):
    """
    Decrypt a string that contains a GPG header.
    """
    if not string.startswith(GPG_HEADER):
        raise ValueError("String does not start with GPG header")
    if not string.endswith(GPG_FOOTER):
        raise ValueError("String does not end with GPG footer")
    string = string[len(GPG_HEADER):-len(GPG_FOOTER)]
    return _decrypt_string(string)


