def _GetDelayImportTimestamps(self, pefile_object):
    """Retrieves timestamps from delay import entries, if available.

    Args:
      pefile_object (pefile.PE): pefile object.

    Returns:
      tuple[str, int]: name of the DLL being imported and the second is
          the timestamp of the entry.
    """
    delay_imports = pefile_object.DIRECTORY_ENTRY_DELAY_IMPORT
    if not delay_imports:
      return

    for delay_import in delay_imports:
      for delay_import_entry in delay_import.imports:
        if delay_import_entry.name:
          yield (delay_import_entry.name.decode('utf-8'),
                 delay_import_entry.timestamp)

