def is_schema_of_relay(schema: GraphQLSchema) -> bool:
    """Check whether this schema uses the relay naming convention.

    GraphQL schema define root types for each type of operation. These types are the
    same as any other type and can be named in any manner, however there is a common
    naming convention:

    schema {
      query: Query
      mutation: Mutation
    }

    When using this naming convention, the schema description can be omitted.
    """
    return (
        schema.query_type is not None
        and schema.mutation_type is not None
        and schema.subscription_type is not None
    )


