def interfaces_addrs(iface=None):
    """
    Return the IPv4 addresses assigned to the specified interface,
    or to all interfaces if ``iface`` is not specified.

    CLI Example:

    .. code-block:: bash

        salt '*' network.interfaces_addrs
    """
    ret = {}
    for iface_name, iface_data in __salt__["network.interfaces"]().items():
        if iface and iface != iface_name:
            continue
        ret[iface_name] = []
        for iface_addr in iface_data.get("inet", []):
            ret[iface_name].append(iface_addr["address"])
    return ret


