def strip_tree(node,
               # Runtime optimization
               iter_node=iter_node, special=ast.AST,
               list=list, isinstance=isinstance, type=type, len=len):
    """Strips an AST by removing all attributes not in _fields.

    Returns a set of the names of all attributes stripped.

    This canonicalizes two trees for comparison purposes.
    """
    if isinstance(node, special):
        return node

    if isinstance(node, list):
        return [strip_tree(n, iter_node, special, list, isinstance, type, len)
                for n in node]

    # We can't use getattr here because it will return the default value
    # for the type.
    stripped = {}
    for name in node._fields:
        value = getattr(node, name)
        if isinstance(value, special):
            stripped[name] = value
        elif isinstance(value, list):
            stripped[name] = [strip_tree(n, iter_node, special, list,
                                         isinstance, type, len)
                              for n in value]
        else:
            stripped[name] = value

    # If the node is an iter_node, we need to strip the body.
    if isinstance(node, iter_node):
        stripped['body'] = [strip_tree(n, iter_node, special, list,
                                       isinstance, type, len)
                            for n in node.body]

    return type(node)(**stripped)

