def find_path(graph:dict, start:str, end:str) -> list:
    """Return path from start to end"""
    path = []
    visited = set()
    stack = [(start, path)]
    while stack:
        node, path = stack.pop()
        if node not in visited:
            visited.add(node)
            path = path + [node]
            if node == end:
                return path
            for next_node in graph.get(node, []):
                if next_node not in visited:
                    stack.append((next_node, path))
    return []


def find_all_paths(graph:dict, start:str, end:str) -> list:
    """Return all paths from start to end"""
    paths = []
    visited = set()
    stack = [(start, [start])]
    while stack:
        node, path = stack.pop()
        if node not in visited:
            visited.add(node)
            path = path + [node]
            if node == end:
                paths.append(path)
            for next_node in graph.get(node, []):
                if next_node not in visited:
                    stack.append((next_node, path))
    return paths


def find_shortest_path(graph:dict, start:str, end:str) -> list:
    """Return shortest path from start to end"""
    paths = find_all_paths(graph, start, end)
    if not paths:
        return []
    return min(paths, key=len)


def find_shortest_path_length(graph:dict, start:str, end:str) -> int:
    """Return shortest path length from start to end"""
    return len(find_shortest_path(graph, start, end))


