def parse(tokens):
    """A generator which yields AST nodes"""
    for token in tokens:
        if token.type == 'text':
            yield Text(token.value)
        elif token.type == 'variable':
            yield Variable(token.value)
        elif token.type == 'block':
            yield Block(token.value, parse(tokens))


def render(template, context):
    """Render a template with a given context"""
    for node in parse(tokenise(template)):
        if isinstance(node, Text):
            yield node.value
        elif isinstance(node, Variable):
            yield context[node.value]
        elif isinstance(node, Block):
            if node.value in context:
                for child in node.children:
                    yield render(child, context)


def render_string(template, context):
    """Render a template with a given context"""
    return ''.join(render(template, context))


