        The parsed distribution.
    """
    distribution_type = cp.get(section, name)
    distribution_args = cp.get(section, name + "_args")
    return read_distribution(distribution_type, distribution_args)


def read_distribution(distribution_type, distribution_args):
    """Returns a PyCBC distribution instance for a given distribution type
    and arguments.

    Parameters
    ----------
    distribution_type : string
        The type of distribution to read.
    distribution_args : string
        The arguments to pass to the distribution.

    Returns
    -------
    Distribution
        The parsed distribution.
    """
    if distribution_type == "Uniform":
        return Uniform(*json.loads(distribution_args))
    elif distribution_type == "Normal":
        return Normal(*json.loads(distribution_args))
    elif distribution_type == "LogNormal":
        return LogNormal(*json.loads(distribution_args))
    elif distribution_type == "Exponential":
        return Exponential(*json.loads(distribution_args))
    elif distribution_type == "Gamma":
        return Gamma(*json.loads(distribution_args))
    elif distribution_type == "Beta":
        return Beta(*json.loads(distribution_args))
    elif distribution_type == "Logistic":
        return Logistic(*json.loads(distribution_args))
    elif distribution_type == "Cauchy":
