        """Initializes a connection to the smtp server

        :return: True on success, False otherwise
        """
        if self.connected:
            return True
        try:
            self.smtp = smtplib.SMTP(self.host, self.port)
            self.smtp.ehlo()
            if self.tls:
                self.smtp.starttls()
                self.smtp.ehlo()
