def describe_schema_versions(self, ):
    """
    for each schema version present in the cluster, returns a list of nodes at that version.
    hosts that do not respond will be under the key DatabaseDescriptor.INITIAL_VERSION.
    the cluster is all on the same version if the size of the map is 1.
    """
    schema_versions = {}
    for host in self.hosts:
        try:
            version = host.get_cassandra_version()
            if version not in schema_versions:
                schema_versions[version] = []
            schema_versions[version].append(host)
        except Exception:
            schema_versions[DatabaseDescriptor.INITIAL_VERSION] = schema_versions.get(DatabaseDescriptor.INITIAL_VERSION, [])
            schema_versions[DatabaseDescriptor.INITIAL_VERSION].append(host)
    return schema_versions

