def disconnect(self, receiver=None, sender=None, dispatch_uid=None):
        """
        Disconnect receiver from sender for signal.

        If weak references are used, disconnect need not be called. The receiver
        will be remove from dispatch automatically.

        Arguments:

            receiver
                The registered receiver to disconnect. May be none if
                dispatch_uid is specified.

            sender
                The registered sender to disconnect

            dispatch_uid
                the unique identifier of the receiver to disconnect
        """
        if dispatch_uid:
            receiver = self._find_receiver(dispatch_uid)
            if receiver is None:
                raise ValueError("Receiver %s not connected to %s" % (dispatch_uid, self))
        else:
            if receiver is None:
                raise ValueError("Receiver must be provided if dispatch_uid is not specified.")

        if sender is None:
            sender = self.sender

        if not isinstance(sender, (list, tuple)):
            sender = [sender]

        for s in sender:
            if s not in self._senders:
                raise ValueError("Sender %s not connected to %s" % (s, self))

            if receiver not in self._senders[s]:
                raise ValueError("Receiver %s not connected to %s" % (receiver, self))

            self._senders[s].remove(receiver)

            if not self._senders[s]:
                del self._senders[s]

