def descr2tabledef(descr, table_type='binary', write_bitcols=False):
    """
    Create a FITS table def from the input numpy descriptor.

    parameters
    ----------
    descr: list
        A numpy recarray type descriptor  array.dtype.descr

    returns
    -------
    names, formats, dims: tuple of lists
        These are the ttyp, tform and tdim header entries
        for each field.  dim entries may be None
    """
    names = []
    formats = []
    dims = []
    for name, dtype in descr:
        if dtype.kind == 'V':
            if write_bitcols:
                formats.append('1J')
                dims.append(None)
            else:
                formats.append('1K')
                dims.append(None)
        else:
            if dtype.kind == 'i':
                formats.append('J')
            elif dtype.kind == 'f':
                formats.append('E')
            elif dtype.kind == 'b':
                formats.append('L')
            elif dtype.kind == 'u':
                formats.append('J')
            elif dtype.kind == 'c':
                formats.append('D')
            else:
                raise ValueError('unsupported dtype: %s' % dtype)
            dims.append(None)
        names.append(name)
    if table_type == 'ascii':
        formats = ['A%d' % len(f) for f in formats]
        dims = [None] * len(formats)
    return names, formats, dims

