def CopyToDateTimeString(self):
    """Copies the Cocoa timestamp to a date and time string.

    Returns:
      str: date and time value formatted as: YYYY-MM-DD hh:mm:ss.###### or
          None if the timestamp cannot be copied to a date and time string.
    """
    if self.timestamp is None:
      return None

    date_time_string = self._CopyToDateTimeString()
    if date_time_string is None:
      return None

    return '{0:s} {1:s}'.format(date_time_string, self.time_zone)

