def read_upload(up_file, data_model=None):
    """
    take a file that should be ready for upload
    using the data model, check that all required columns are full,
    and that all numeric data is in fact numeric.
    print out warnings for any validation problems
    return True if there were no problems, otherwise return False
    """
    # check that all required columns are present
    if data_model is not None:
        for col in data_model.required_columns:
            if col not in up_file.columns:
                print(f"{col} is required but not present in the upload file")
                return False
    # check that all numeric columns are numeric
    if data_model is not None:
        for col in data_model.numeric_columns:
            if col not in up_file.columns:
                print(f"{col} is required but not present in the upload file")
                return False
            else:
                if not up_file[col].dtype.kind in 'biufc':
                    print(f"{col} is not numeric")
                    return False
    return True

