def _json_decode_hook(dct: Dict[str, Any]) -> Any:
    """
    Custom decoder for JSON.
    """
    if "__type__" in dct:
        if dct["__type__"] == "datetime":
            return datetime.datetime.strptime(dct["value"], "%Y-%m-%dT%H:%M:%S.%f")
        elif dct["__type__"] == "timedelta":
            return datetime.timedelta(seconds=dct["value"])
        elif dct["__type__"] == "uuid":
            return uuid.UUID(dct["value"])
        elif dct["__type__"] == "enum":
            return dct["value"]
        elif dct["__type__"] == "set":
            return set(dct["value"])
        elif dct["__type__"] == "frozenset":
            return frozenset(dct["value"])
        elif dct["__type__"] == "decimal":
            return decimal.Decimal(dct["value"])
