    """
    if app is None:
        app = current_app

    if app is None:
        raise RuntimeError("No Flask app found. Please pass an app instance "
                           "to get_setting()")

    if app.config.get('FLASKS3_SETTINGS'):
        settings = app.config['FLASKS3_SETTINGS']
    else:
        settings = DEFAULT_SETTINGS

    if name in settings:
        return settings[name]

    return None

