                         for the symmetric difference operation
        Returns:
            DFA: The resulting DFA
        """
        if not isinstance(other, DFA):
            raise TypeError("other must be an instance of DFA")
        if self.is_minimized() or other.is_minimized():
            raise ValueError("DFAs must not be minimized")
        if self.alphabet != other.alphabet:
            raise ValueError("Alphabets of DFAs must be equal")
