def convert_ipynb(ipynb_file):
    """Converts a single ipynb file into a rst file with the same name."""
    rst_file = os.path.splitext(ipynb_file)[0] + '.rst'
    with open(ipynb_file, 'r') as f:
        ipynb = json.load(f)
    with open(rst_file, 'w') as f:
        f.write(ipynb_to_rst(ipynb))


def ipynb_to_rst(ipynb):
    """Converts an ipynb dict into a rst string."""
    rst = ''
    for cell in ipynb['cells']:
        if cell['cell_type'] == 'markdown':
            rst += cell['source'] + '\n'
        elif cell['cell_type'] == 'code':
            rst += '.. code-block:: python\n\n'
            rst += cell['source'] + '\n'
            if 'outputs' in cell:
                for output in cell['outputs']:
                    if output['output_type'] == 'execute_result':
                        rst += '.. code-block:: python\n\n'
                        rst += output['data']['text/plain'] + '\n'
                    elif output['output_type'] == 'stream':
                        rst += '.. code-block:: python\n\n'
                        rst += output['text'] + '\n'
    return rst


