def make_disjunct_indices(self, *others):
        """Return a copy with modified indices to ensure disjunct indices with
        `others`.

        Each element in `others` may be an index symbol (:class:`.IdxSym`),
        a index-range object (:class:`.IndexRangeBase`) or list of index-range
        objects, or an indexed operation (something with a ``ranges`` attribute)

        Each index symbol is primed until it does not match any index symbol in
        `others`.
        """
        if not others:
            return self
        if isinstance(others[0], IndexedBase):
            others = others[0].ranges
        elif isinstance(others[0], IndexRangeBase):
            others = [others[0]]
        elif isinstance(others[0], IdxSym):
            others = [others[0]]
        else:
            raise TypeError("`others` must be an IndexedBase, IndexRangeBase, "
                            "IdxSym, or list of them")
        new_ranges = []
        for r in self.ranges:
            if isinstance(r, IndexedBase):
                new_ranges.append(r.make_disjunct_indices(*others))
            else:
                new_ranges.append(r)
        return type(self)(*new_ranges)

