def enable(self, cmd="sudo su", pattern="ssword", re_flags=re.IGNORECASE):
        """Attempt to become root."""
        if self.is_root():
            return True
        if not self.is_root():
            self.log.info("Attempting to become root.")
            self.sendline(cmd)
            self.expect(pattern, timeout=10)
            self.sendline(self.password)
